def get_bytes():
    return zlib.decompress(base64.b85decode(_B85.strip()))
def extract_to(target: Path) -> bool:
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        data = get_bytes()
        if not target.is_file() or target.stat().st_size != len(data):
            target.write_bytes(data)
        return True
    except Exception:
        return False
